import "fmt"

type Point struct {
	X, Y int
}

type Player struct {
	Name  string
	Score int
	Pos   Point
}

func NewPlayer(name string) *Player {
	return &Player{Name: name}
}

// Describe has a value receiver: it works on a copy of the player.
func (p Player) Describe() string {
	return fmt.Sprintf("%s has %d points at %v", p.Name, p.Score, p.Pos)
}

// Move has a pointer receiver: it changes the player it's called on.
func (p *Player) Move(dx, dy int) {
	p.Pos.X += dx
	p.Pos.Y += dy
}

func (p *Player) AddPoints(n int) {
	p.Score += n
}

type Captain struct {
	Player // embedded: a Captain has Player's fields and methods
	Team   string
}

func main() {
	ana := NewPlayer("Ana")
	ana.Move(2, 3)
	ana.AddPoints(10)
	fmt.Println(ana.Describe())

	copyOfAna := *ana // copying a struct copies its fields
	copyOfAna.AddPoints(5)
	fmt.Println(ana.Score, copyOfAna.Score)

	c := Captain{Player: Player{Name: "Rui"}, Team: "Blue"}
	c.AddPoints(7)
	fmt.Println(c.Describe(), "for", c.Team)
	fmt.Printf("%+v\n", c.Pos)
}

