import (
	"errors"
	"fmt"
	"strconv"
)

// ErrNotFound is a sentinel error: callers compare against it with errors.Is.
var ErrNotFound = errors.New("not found")

// RangeError is a custom error type carrying details.
type RangeError struct {
	Value, Min, Max int
}

func (e *RangeError) Error() string {
	return fmt.Sprintf("%d is outside %d..%d", e.Value, e.Min, e.Max)
}

var stock = map[string]int{"apple": 5}

func quantity(item string) (int, error) {
	n, ok := stock[item]
	if !ok {
		return 0, fmt.Errorf("quantity of %q: %w", item, ErrNotFound) // %w wraps
	}
	return n, nil
}

func parseAge(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("parse age: %w", err)
	}
	if n < 0 || n > 150 {
		return 0, &RangeError{Value: n, Min: 0, Max: 150}
	}
	return n, nil
}

func main() {
	if _, err := quantity("pear"); err != nil {
		fmt.Println(err)
		fmt.Println(errors.Is(err, ErrNotFound))
	}

	for _, s := range []string{"42", "abc", "200"} {
		age, err := parseAge(s)
		var rangeErr *RangeError
		switch {
		case err == nil:
			fmt.Println("age", age)
		case errors.As(err, &rangeErr):
			fmt.Println("out of range by", rangeErr.Value-rangeErr.Max)
		default:
			fmt.Println("error:", err)
		}
	}
}

