package main

import (
	"errors"
	"fmt"
	"strings"
)

// Notifier is anything that can deliver a message to a target.
type Notifier interface {
	Notify(target, text string) error
}

var (
	ErrUnknownChannel = errors.New("unknown channel")
	ErrBadTarget      = errors.New("bad target")
)

// Email sends messages by email.
type Email struct{ From string }

func (e Email) Notify(target, text string) error {
	if !strings.Contains(target, "@") {
		return fmt.Errorf("email to %q: %w", target, ErrBadTarget)
	}
	fmt.Printf("email from %s to %s: %s\n", e.From, target, text)
	return nil
}

// SMS sends text messages to phone numbers.
type SMS struct{}

// TODO: give SMS a Notify method, so that it satisfies Notifier. A target must start with
// "+" (otherwise wrap ErrBadTarget, as Email does); print "sms to <target>: <text>".

// LineError says which line of the input was wrong, and why.
type LineError struct {
	Line int
	Err  error
}

func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }

// Unwrap lets errors.Is and errors.As look at the error inside.
func (e *LineError) Unwrap() error { return e.Err }

var notifiers = map[string]Notifier{
	"email": Email{From: "alerts@example.com"},
	"sms":   SMS{},
}

// send parses one "channel|target|text" line and sends the message.
func send(lineNo int, line string) error {
	parts := strings.SplitN(line, "|", 3)
	if len(parts) != 3 {
		return &LineError{Line: lineNo, Err: errors.New("want channel|target|text")}
	}
	// TODO: look the channel up in notifiers. If it's missing, return a *LineError wrapping
	// fmt.Errorf("%q: %w", parts[0], ErrUnknownChannel). Otherwise call its Notify method,
	// and wrap any error it returns in a *LineError too.
	return nil
}

const input = `email|ops@example.com|Disk almost full
sms|+351900000001|Server down
pager|team|Wake up
email|nobody|Missing at sign
sms|+351900000002
sms|900000003|No plus sign`

func main() {
	sent, unknown, badTarget := 0, 0, 0
	for i, line := range strings.Split(input, "\n") {
		err := send(i+1, line)
		var lineErr *LineError
		switch {
		case err == nil:
			sent++
		case errors.Is(err, ErrUnknownChannel):
			unknown++
			fmt.Println("skipped:", err)
		case errors.Is(err, ErrBadTarget):
			badTarget++
			fmt.Println("failed:", err)
		case errors.As(err, &lineErr):
			fmt.Printf("malformed line %d: %v\n", lineErr.Line, lineErr.Err)
		}
	}
	fmt.Printf("sent %d, unknown channel %d, bad target %d\n", sent, unknown, badTarget)
}

