import "fmt"

func produce(n int, out chan<- int) {
	for i := 1; i <= n; i++ {
		out <- i
	}
	close(out) // only the sender closes a channel
}

func main() {
	numbers := make(chan int) // unbuffered: each send waits for a receiver
	go produce(5, numbers)
	sum := 0
	for n := range numbers { // stops when the channel is closed
		sum += n
	}
	fmt.Println("sum", sum)

	buffered := make(chan string, 2)
	buffered <- "first"
	buffered <- "second" // fits: the buffer holds two
	fmt.Println(<-buffered, <-buffered)

	v, ok := <-numbers // a closed channel gives the zero value and false
	fmt.Println(v, ok)
}

