import (
	"context"
	"fmt"
	"slices"
	"sync"
	"time"
)

// worker takes job numbers until jobs is closed. Job n takes n*50 ms, unless ctx ends first.
func worker(ctx context.Context, jobs <-chan int, results chan<- string, wg *sync.WaitGroup) {
	defer wg.Done()
	for n := range jobs {
		select {
		case <-ctx.Done():
			results <- fmt.Sprintf("job %d: %v", n, ctx.Err())
		case <-time.After(time.Duration(n) * 50 * time.Millisecond):
			results <- fmt.Sprintf("job %d: done", n)
		}
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 275*time.Millisecond)
	defer cancel()

	jobs := make(chan int)
	results := make(chan string)
	var wg sync.WaitGroup
	for range 3 {
		wg.Add(1)
		go worker(ctx, jobs, results, &wg)
	}
	go func() {
		for n := 1; n <= 6; n++ {
			jobs <- n
		}
		close(jobs)
	}()
	go func() {
		wg.Wait()
		close(results) // every worker has finished: no more results
	}()

	var lines []string
	for r := range results {
		lines = append(lines, r)
	}
	slices.Sort(lines)
	for _, line := range lines {
		fmt.Println(line)
	}
}

