package main

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"
	"sync"
	"time"
)

// Site is a pretend website: checking it takes Delay, and a site that's Down fails.
type Site struct {
	Name  string
	Delay time.Duration
	Down  bool
}

var ErrDown = errors.New("site is down")

// check pretends to fetch the site's home page, and gives up when ctx is done.
func check(ctx context.Context, s Site) error {
	select {
	case <-time.After(s.Delay):
		if s.Down {
			return ErrDown
		}
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

type Result struct {
	Name   string
	Status string
}

// Counter counts the checks made, from many goroutines at once.
type Counter struct {
	// TODO: protect n with a sync.Mutex, so that go run -race . reports no data race
	n int
}

func (c *Counter) Inc() {
	// TODO: hold the lock while you change n
	c.n++
}

// checkAll checks every site using `workers` goroutines, giving each check `timeout`.
func checkAll(sites []Site, workers int, timeout time.Duration, counter *Counter) []Result {
	jobs := make(chan Site)
	results := make(chan Result)
	var wg sync.WaitGroup
	// TODO: start `workers` goroutines (wg.Add(1) for each, defer wg.Done() inside). Each
	// takes sites from jobs until it's closed. For each site: create a context with
	// context.WithTimeout(context.Background(), timeout), call check, then cancel() and
	// counter.Inc(), and send a Result whose Status is "up", "down" (errors.Is(err, ErrDown))
	// or "timed out" (errors.Is(err, context.DeadlineExceeded)).
	go func() {
		for _, s := range sites {
			jobs <- s
		}
		close(jobs)
	}()
	go func() {
		wg.Wait()
		close(results) // every worker has finished, so no more results are coming
	}()

	var all []Result
	for r := range results {
		all = append(all, r)
	}
	slices.SortFunc(all, func(a, b Result) int { return strings.Compare(a.Name, b.Name) })
	return all
}

func main() {
	ms := time.Millisecond
	sites := []Site{
		{"alpha.example", 20 * ms, false},
		{"bravo.example", 40 * ms, false},
		{"charlie.example", 10 * ms, true},
		{"delta.example", 2 * time.Second, false}, // far too slow
		{"echo.example", 30 * ms, false},
		{"foxtrot.example", 50 * ms, false},
		{"golf.example", 20 * ms, true},
		{"hotel.example", 10 * ms, false},
		{"india.example", 40 * ms, false},
		{"juliet.example", 30 * ms, false},
		{"kilo.example", 20 * ms, false},
		{"lima.example", 10 * ms, false},
	}
	var counter Counter
	start := time.Now()
	results := checkAll(sites, 4, 500*ms, &counter)
	up, down, timedOut := 0, 0, 0
	for _, r := range results {
		fmt.Printf("%-16s %s\n", r.Name, r.Status)
		switch r.Status {
		case "up":
			up++
		case "down":
			down++
		default:
			timedOut++
		}
	}
	fmt.Printf("checked %d sites: %d up, %d down, %d timed out\n", counter.n, up, down, timedOut)
	fmt.Printf("took %v\n", time.Since(start).Round(100*ms))
}

