// Server routes requests to handlers that use the store.
type Server struct {
	store *Store
	mux   *http.ServeMux
}

func NewServer(store *Store) *Server {
	s := &Server{store: store, mux: http.NewServeMux()}
	s.mux.HandleFunc("GET /tasks", s.listTasks)
	s.mux.HandleFunc("POST /tasks", s.createTask)
	s.mux.HandleFunc("GET /tasks/{id}", s.getTask)
	s.mux.HandleFunc("POST /tasks/{id}/done", s.completeTask)
	s.mux.HandleFunc("DELETE /tasks/{id}", s.deleteTask)
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mux.ServeHTTP(w, r)
}

// writeJSON sends v as JSON with the given status code.
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

// taskID reads the {id} part of the path; ok is false if it isn't a whole number.
func taskID(r *http.Request) (id int, ok bool) {
	id, err := strconv.Atoi(r.PathValue("id"))
	return id, err == nil
}

// cleanTitle trims the white space around a title.
func cleanTitle(title string) string {
	return strings.TrimSpace(title)
}

func (s *Server) listTasks(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.store.List())
}

