// do sends one request to the handler and returns the recorded response.
func do(t *testing.T, h http.Handler, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestCreateAndGetTask(t *testing.T) {
	srv := NewServer(NewStore())
	rec := do(t, srv, "POST", "/tasks", `{"title": "Buy milk"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: status %d, want 201: %s", rec.Code, rec.Body)
	}
	var created Task
	if err := json.NewDecoder(rec.Body).Decode(&created); err != nil {
		t.Fatal(err)
	}
	if created.ID != 1 || created.Title != "Buy milk" || created.Done {
		t.Fatalf("created %+v", created)
	}

	rec = do(t, srv, "GET", "/tasks/1", "")
	if rec.Code != http.StatusOK || !strings.Contains(rec.Body.String(), `"title":"Buy milk"`) {
		t.Fatalf("get: status %d, body %s", rec.Code, rec.Body)
	}
}

func TestCreateRejectsBlankTitles(t *testing.T) {
	for _, body := range []string{`{"title": "   "}`, `{}`, `not json`} {
		rec := do(t, NewServer(NewStore()), "POST", "/tasks", body)
		if rec.Code != http.StatusBadRequest {
			t.Errorf("body %s: status %d, want 400", body, rec.Code)
		}
	}
}

func TestGetMissingAndBadIDs(t *testing.T) {
	srv := NewServer(NewStore())
	tests := []struct {
		path string
		want int
	}{
		{"/tasks/99", http.StatusNotFound},
		{"/tasks/abc", http.StatusBadRequest},
	}
	for _, tt := range tests {
		if rec := do(t, srv, "GET", tt.path, ""); rec.Code != tt.want {
			t.Errorf("GET %s: status %d, want %d", tt.path, rec.Code, tt.want)
		}
	}
}

func TestListIsOrderedByID(t *testing.T) {
	srv := NewServer(NewStore())
	for _, title := range []string{"one", "two", "three"} {
		do(t, srv, "POST", "/tasks", `{"title": "`+title+`"}`)
	}
	var list []Task
	json.NewDecoder(do(t, srv, "GET", "/tasks", "").Body).Decode(&list)
	if len(list) != 3 || list[0].Title != "one" || list[2].ID != 3 {
		t.Fatalf("list %+v", list)
	}
}

