// These tests describe the service. Write NewHandler() http.Handler so that they pass.

func request(h http.Handler, method, path, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

// shorten posts a URL to /links and decodes the JSON reply.
func shorten(t *testing.T, h http.Handler, url string) (int, map[string]any) {
	t.Helper()
	body, _ := json.Marshal(map[string]string{"url": url})
	rec := request(h, "POST", "/links", string(body))
	var reply map[string]any
	json.NewDecoder(rec.Body).Decode(&reply)
	return rec.Code, reply
}

func TestShortenAndFollow(t *testing.T) {
	h := NewHandler()
	status, reply := shorten(t, h, "https://go.dev/doc/")
	if status != http.StatusCreated {
		t.Fatalf("POST /links: status %d, want 201 (reply %v)", status, reply)
	}
	code, _ := reply["code"].(string)
	if code == "" {
		t.Fatalf("no code in reply %v", reply)
	}
	rec := request(h, "GET", "/"+code, "")
	if rec.Code != http.StatusFound {
		t.Fatalf("GET /%s: status %d, want 302", code, rec.Code)
	}
	if loc := rec.Header().Get("Location"); loc != "https://go.dev/doc/" {
		t.Errorf("Location = %q, want https://go.dev/doc/", loc)
	}
}

func TestRejectsBadURLs(t *testing.T) {
	for _, url := range []string{"", "go.dev", "ftp://example.com/file", "https://"} {
		if status, _ := shorten(t, NewHandler(), url); status != http.StatusBadRequest {
			t.Errorf("url %q: status %d, want 400", url, status)
		}
	}
}

func TestUnknownCodeIsNotFound(t *testing.T) {
	if rec := request(NewHandler(), "GET", "/nope", ""); rec.Code != http.StatusNotFound {
		t.Errorf("GET /nope: status %d, want 404", rec.Code)
	}
}

func TestStatsCountVisitsFromConcurrentRequests(t *testing.T) {
	h := NewHandler()
	_, reply := shorten(t, h, "https://example.com/")
	code, _ := reply["code"].(string)

	var wg sync.WaitGroup
	for range 50 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			request(h, "GET", "/"+code, "")
		}()
	}
	wg.Wait()

	rec := request(h, "GET", "/links/"+code, "")
	var stats struct {
		Code   string `json:"code"`
		URL    string `json:"url"`
		Visits int    `json:"visits"`
	}
	if err := json.NewDecoder(rec.Body).Decode(&stats); err != nil {
		t.Fatalf("GET /links/%s: %v (status %d)", code, err, rec.Code)
	}
	if stats.Visits != 50 || stats.URL != "https://example.com/" || stats.Code != code {
		t.Errorf("stats %+v, want 50 visits to https://example.com/", stats)
	}
}
